//
// Generates a PLACEHOLDER src/aws-exports.js so the frontend can type-check and
// build WITHOUT a deployed environment. Used by CI (no-secrets PR validation)
// and for local offline builds.
//
// In a real deployment the file is generated by configure_auth.sh against the
// deployed CloudFormation stacks. These placeholder values are never valid for
// runtime use — they exist only to satisfy the compiler/bundler.
//
// The shape here must match what the consumers read:
//   - src/index.tsx                              (Amplify.configure)
//   - src/components/session-management/authenticator.ts
//   - src/components/pages/swagger/swagger.tsx   (API.REST[*].endpoint)

import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const outFile = join(here, '..', 'src', 'aws-exports.js');
const region = 'us-east-1';
const restEndpoint = (ctx) =>
  `https://stub0000000.execute-api.${region}.amazonaws.com/prod/${ctx}`;

const contents = `// AUTO-GENERATED PLACEHOLDER — do NOT deploy with these values.
// Regenerate the real file with configure_auth.sh against a deployed environment.
const awsmobile = {
  Auth: {
    Cognito: {
      userPoolId: '${region}_STUB00000',
      userPoolClientId: 'stubuserpoolclientid00000000',
      loginWith: {
        oauth: {
          domain: 'stub.auth.${region}.amazoncognito.com',
          scopes: ['email', 'profile', 'openid'],
          redirectSignIn: ['http://localhost:3000/'],
          redirectSignOut: ['http://localhost:3000/'],
          responseType: 'code'
        }
      }
    },
    cookieStorage: {
      expires: 2
    }
  },
  API: {
    REST: {
      ProjectsAPI: { endpoint: '${restEndpoint('projects')}', region: '${region}' },
      PublishingAPI: { endpoint: '${restEndpoint('publishing')}', region: '${region}' },
      PackagingAPI: { endpoint: '${restEndpoint('packaging')}', region: '${region}' },
      ProvisioningAPI: { endpoint: '${restEndpoint('provisioning')}', region: '${region}' }
    }
  }
};
export default awsmobile;
`;

writeFileSync(outFile, contents);
console.log(`Wrote placeholder aws-exports to ${outFile}`);
